head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;
scwin.prevRow = -1;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 선물옵션 표준코드 관리를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    /**
     * SrM-000243255
     */
    if (!await scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkSearchCondition
 * @description SrM-000243255  조회조건을 체크 (표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 / 날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSearchCondition = async function() {
    const sStdCd = txb_pSTD_CD.getValue();
    const sIsuKorNm = txb_pISU_NM.getValue();
    const sSDateFrom = edt_pSTD_CD_GRNT_DD_SDATE.getValue(); // 코드부여일(from)
    const sSDateTo = edt_pSTD_CD_GRNT_DD_EDATE.getValue(); // 코드부여일(to)

    if (sStdCd === "" && sIsuKorNm === "") {
        if (sSDateFrom === "" && sSDateTo === "") {
            const msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명] 중 1개 이상의 조건을 입력하거나, \n" + "[코드부여일]의 검색기간을 1년 이내로 입력하세요.";
            await $c.win.alert(msg);
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom !== "" && sSDateTo !== "") {
            if (Number($c.ut.cGetPlusYear(sSDateFrom, 1)) < Number(sSDateTo)) {
                await $c.win.alert("코드부여일의 검색기간은 1년 이내로 입력하세요.");
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom !== "" || sSDateTo !== "") {
            await $c.win.alert("코드부여일의 검색기간은 1년 이내로 입력하세요.");
            if (sSDateFrom === "") {
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
            } else {
                edt_pSTD_CD_GRNT_DD_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getFutoptUpclssCd
 * @description 조회를 위한 선물 옵션 유무를 생성한다
 * @returns {void}
 * @hidden N
 */
scwin.getFutoptUpclssCd = function() {
    let strFutoptUpclssCd = "";
    if (ckb_FUT_YN.getValue() === "Y") strFutoptUpclssCd += "'1'";
    if (ckb_OPT_YN.getValue() === "Y") strFutoptUpclssCd += ((strFutoptUpclssCd.length > 0) ? ",'2'" : "'2'");
    if (strFutoptUpclssCd.length > 0) strFutoptUpclssCd = "(" + strFutoptUpclssCd + ")";
    return strFutoptUpclssCd;
};

/**
 * @method
 * @name getCfCdtyp
 * @description 조회를 위한 상품선택을 생성한다
 * @returns {void}
 * @hidden N
 */
scwin.getCfCdtyp = function() {
    let strCFI = "";
    if (ckb_CFI_CD_11.getValue() === "Y") strCFI += "'11'";
    if (ckb_CFI_CD_12.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'12'" : "'12'");
    if (ckb_CFI_CD_13.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'13'" : "'13'");
    if (ckb_CFI_CD_21.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'21'" : "'21'");
    if (ckb_CFI_CD_22.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'22'" : "'22'");
    if (ckb_CFI_CD_31.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'31'" : "'31'");
    if (ckb_CFI_CD_32.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'32'" : "'32'");
    if (ckb_CFI_CD_33.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'33'" : "'33'");
    if (ckb_CFI_CD_34.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'34'" : "'34'");
    if (ckb_CFI_CD_35.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'35'" : "'35'");
    if (ckb_CFI_CD_41.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'41'" : "'41'");
    if (ckb_CFI_CD_42.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'42'" : "'42'");
    if (ckb_CFI_CD_43.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'43'" : "'43'");
    if (ckb_CFI_CD_44.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'44'" : "'44'");
    if (ckb_CFI_CD_51.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'51'" : "'51'");
    if (ckb_CFI_CD_52.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'52'" : "'52'");
    if (ckb_CFI_CD_47.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'47'" : "'47'");
    if (ckb_CFI_CD_99.getValue() === "Y") strCFI += ((strCFI.length > 0) ? ",'99'" : "'99'");
    if (strCFI.length > 0) strCFI = "(" + strCFI + ")";
    return strCFI;
};

/**
 * @method
 * @name setCfCdEnable
 * @description 상품선택 체크박스를 컨트롤 한다
 * @param {*} bEnable bEnable
 * @returns {void}
 * @hidden N
 */
scwin.setCfCdEnable = function(bEnable) {
    ckb_CFI_CD_11.setDisabled(bEnable);
    ckb_CFI_CD_12.setDisabled(bEnable);
    ckb_CFI_CD_13.setDisabled(bEnable);
    ckb_CFI_CD_21.setDisabled(bEnable);
    ckb_CFI_CD_22.setDisabled(bEnable);
    ckb_CFI_CD_31.setDisabled(bEnable);
    ckb_CFI_CD_32.setDisabled(bEnable);
    ckb_CFI_CD_33.setDisabled(bEnable);
    ckb_CFI_CD_34.setDisabled(bEnable);
    ckb_CFI_CD_35.setDisabled(bEnable);
    ckb_CFI_CD_41.setDisabled(bEnable);
    ckb_CFI_CD_42.setDisabled(bEnable);
    ckb_CFI_CD_43.setDisabled(bEnable);
    ckb_CFI_CD_44.setDisabled(bEnable);
    ckb_CFI_CD_51.setDisabled(bEnable);
    ckb_CFI_CD_52.setDisabled(bEnable);
    ckb_CFI_CD_99.setDisabled(bEnable);
    ckb_CFI_CD_47.setDisabled(bEnable);
};

/**
 * @method
 * @name setCfiCd
 * @description SFI코드를 생성한다
 * @returns {void}
 * @hidden N
 */
scwin.setCfiCd = function() {
    // 수정기능이 없어져 return 처리 한다
    return;
    let cfi_cd = "";
    const fut_opt_cd = cmb_FUTOPT_UPCLSS_CD.getValue(); // 선물/옵션 구분
    const f_bs_ass_cd = cmb_FNC_ULY_TP_CD.getValue(); // 금융(옵션)기초자산
    const c_bs_ass_cd = cmb_PROD_ULY_TP_CD.getValue(); // 상품기초자산
    const sttl_mth = cmb_ELW_SETL_METHD_CD.getValue(); // 결제방법
    const std_yn = cmb_STD_YN.getValue(); // 표준화여부
    const fn_gds_fut_cd = cmb_FNC_PROD_FUT_TP_CD.getValue(); // 금융/상품 선물 구분
    const call_put_cd = cmb_CALLPUT_TP_CD.getValue(); // call/put 구분
    const ame_eur_cd = cmb_EXER_TP_CD.getValue(); // 미국식 /유럽식 구분

    if (txb_pSTD_CD.getValue() === "") {
        return;
    } else if (fut_opt_cd === "1") {
        // 선물 인 경우

        cfi_cd = fut_opt_cd;
        cfi_cd += fn_gds_fut_cd;
        if (fn_gds_fut_cd === "F") {
            cfi_cd += f_bs_ass_cd;
        } else if (fn_gds_fut_cd === "C") {
            cfi_cd += c_bs_ass_cd;
        }
        cfi_cd += sttl_mth;
        cfi_cd += std_yn;
        cfi_cd += "X";
    } else if (fut_opt_cd === "2") {
        // 옵션인 경우

        cfi_cd = fut_opt_cd;
        cfi_cd += call_put_cd;
        cfi_cd += ame_eur_cd;
        cfi_cd += f_bs_ass_cd;
        cfi_cd += sttl_mth;
        cfi_cd += std_yn;
    }
    txb_CFI_CD.setValue(cfi_cd);
};

/**
 * @method
 * @name ins_modify
 * @description 선물옵션 표준코드 관리 수정 한다. screenProcsTpCd 03
 * @param {String} mflag mflag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function(mflag) {
    const screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }

        /* CFI 코드 값과 상관없이 수정 되도록 변경 (HSW 요청. 20180605)
        if(txb_CFI_CD.value =="" || txb_CFI_CD.value.indexOf(" ") == "" ) {
        	alert( getMessageParam("MSG-A005", "CFI코드") );
        	txb_CFI_CD.focus();
        	return false;
        }
         */

        if (mflag === "N") return;
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/StdCdFtrOptInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    let str_cfi = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
    let temp = cmb_cb_p_group.getValue(); // 선택된그룹

    // 카테고리셋팅
    cfi = str_cfi.substring(0, 1); // 카테고리

    // 그룹
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();

    // 1차속성
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();

    // 2차속성
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();

    // 3차속성
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();

    // 4차속성
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    let temp = str_cfi.substring(0, 1); // 카테고리

    if (temp === 'F') {
        ins_cfi_set(dts_cfi_group, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "15", "F", "", "", "G");
    } else if (temp === 'O') {
        ins_cfi_set(dts_cfi_group, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "16", "O", "", "", "G");
    } else if (temp === 'K') {
        ins_cfi_set(dts_cfi_group, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "26", "K", "", "", "G");
    } else {
        ins_cfi_set(dts_cfi_group, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "15", "F", "", "", "G");
    }
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    // PanelToGroupBox(panel_3);
    // PanelToGroupBox(panel_4);

    scwin.setCfCdEnable(false);
    ins_combo_set(dts_FUTOPT_LIST_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "03409", "SEL"); // 03409 - 선물옵션상장구분코드
    ins_combo_set(dts_FUTOPT_UPCLSS_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "02512", "SEL"); // 02512 - 선물옵션대분류코드
    ins_combo_set(dts_FNC_ULY_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "00665", "SEL"); // 00665 - 금융기초자산구분코드
    ins_combo_set(dts_PROD_ULY_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "03410", "SEL"); // 03410 - 상품기초자산구분코드
    ins_combo_set(dts_ELW_SETL_METHD_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "03430", "SEL"); // 03430 - ELW결제방법코드
    ins_combo_set(dts_FNC_PROD_FUT_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "03413", "SEL"); // 03413 - 금융상품선물구분코드
    ins_combo_set(dts_CALLPUT_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "03414", "SEL"); // 03414 - 콜풋구분코드
    ins_combo_set(dts_EXER_TP_CD, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, "00055", "SEL"); // 00055 - 권리행사유형코드

    label_38.hide();
    edt_STD_CD_GRNT_DD.hide();
    fn_setFromToDate1("1y", edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE);
    txb_param1.hide();
    txb_param2.hide();
    label_39.hide();
    edt_EXP_DD.hide();
    txb_DEL_RSN.hide();
    fn_CtrlBtn_temp("no_data");
    txb_pSTD_CD.focus();
};

/**
 * @method
 * @name btn_prcnm_onclick
 * @description 「처리자조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_prcnm_onclick = function() {
