    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};

/**
 * @method
 * @name ckb_FUT_YN_onclick
 * @description ckb_FUT_YN 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ckb_FUT_YN_onclick = function() {
    if (ckb_FUT_YN.getValue() === "Y") {
        scwin.setCfCdEnable(true);
    } else {
        if (ckb_OPT_YN.getValue() === "Y" || ckb_pCFI_CD_NULL_YN.getValue() === "Y") {
            scwin.setCfCdEnable(true);
        } else {
            scwin.setCfCdEnable(false);
        }
    }
};

