/**
 * @method
 * @name cmb_cb_p_group_onselchange
 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    if (cmb_cb_p_group.getValue() !== "") {
        let str_cfi = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
        const temp1 = str_cfi.substring(0, 1); // 카테고리 cfi첫자리
        const temp2 = cmb_cb_p_group.getValue(); // 선택한 그룹
        let temp3 = '15'; // 상품구분코드
        if (temp1 === 'F') {
            temp3 = '15';
        } else if (temp1 === 'O') {
            temp3 = '16';
        } else if (temp1 === 'K') {
            temp3 = '26';
        }
        ins_cfi_set(dts_cfi_attr1, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "1", "");
        ins_cfi_set(dts_cfi_attr2, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "2", "");
        ins_cfi_set(dts_cfi_attr3, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "3", "");
        ins_cfi_set(dts_cfi_attr4, "ULDINS15400.xml", SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "4", "");
        // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.changeCfi();
};
